"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[61404],{7551(e,i,a){a.r(i),a.d(i,{assets:()=>u,contentTitle:()=>l,default:()=>p,frontMatter:()=>n,metadata:()=>r,toc:()=>o});const r=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"O introducere la un curs despre aplica\u021biile practice ale calculului cuantic.","source":"@site/i18n/ro/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"O introducere la un curs despre aplica\u021biile practice ale calculului cuantic.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Calcul cuantic practic pe termen apropiat","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Prezentare general\u0103","permalink":"/learning/courses/quantum-business-foundations/"}}');var t=a(74848),c=a(28453);const n={description:"O introducere la un curs despre aplica\u021biile practice ale calculului cuantic.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},l="Introducere \xeen calculul cuantic practic pe termen scurt {#introduction-to-practical-near-term-quantum-computing}",u={},o=[{value:"Pentru ce ar putea fi utile calculatoarele cuantice",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utilitate \u0219i avantaj cuantic pe termen scurt",id:"near-term-quantum-utility-and-advantage",level:2},{value:"O scurt\u0103 introducere \xeen teoria complexit\u0103\u021bii",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"De la teoria complexit\u0103\u021bii la dovezi practice",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Domenii de aplicare \u0219i studii de caz ale cursului",id:"application-areas-and-course-case-studies",level:2},{value:"Simulare hamiltonian\u0103",id:"hamiltonian-simulation",level:3},{value:"Optimizare",id:"optimization",level:3},{value:"\xcenv\u0103\u021bare automat\u0103 cuantic\u0103",id:"quantum-machine-learning",level:3},{value:"Ecua\u021bii cu derivate par\u021biale",id:"partial-differential-equations",level:3},{value:"Concluzie",id:"conclusion",level:2}];function s(e){const i={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,c.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(i.header,{children:(0,t.jsx)(i.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Introducere \xeen calculul cuantic practic pe termen scurt"})}),"\n",(0,t.jsx)(i.p,{children:"De c\xe2nd calculatoarele cuantice au fost propuse pentru prima dat\u0103, \xeen urm\u0103 cu mai bine de patru decenii, \xeentrebarea a fost: c\xe2t de departe ar putea \xeempinge aceast\u0103 nou\u0103 abordare limitele calculului? Informatica teoretic\u0103 ne-a dat c\xe2teva r\u0103spunsuri captivante. Calculatoarele cuantice ar putea factoriza numere \xeentregi mari dramatic mai rapid dec\xe2t cele mai bune metode clasice cunoscute, ar putea accelera c\u0103utarea nestructurat\u0103 \u0219i ar putea simula sistemele cuantice \xeentr-un mod mai natural. Totu\u0219i, multe dintre aceste idei presupuneau un viitor calculator cuantic la scar\u0103 larg\u0103, tolerant la erori."}),"\n",(0,t.jsx)(i.p,{children:"Tehnologia nu a atins \xeenc\u0103 toate aceste obiective teoretice, dar se \xeembun\u0103t\u0103\u021be\u0219te rapid. Cercet\u0103torii pot folosi acum procesoare cuantice pentru a explora probleme \u0219tiin\u021bifice \u0219i industriale reale. \xcen acest curs vei c\u0103p\u0103ta experien\u021b\u0103 practic\u0103 cu unele dintre cele mai promi\u021b\u0103toare aplica\u021bii. Vom estima propriet\u0103\u021bi de energie joas\u0103 ale unui model molecular complex, vom simula dinamica unei teorii de gauge pe re\u021bea \u0219i vom explora cum poate fi transpus\u0103 o problem\u0103 de portofoliu financiar pe un calculator cuantic. Ne vom uita \u0219i la domenii mai noi, \xeen care abia am \xeenceput s\u0103 \xeen\u021belegem ce ar putea oferi calculatoarele cuantice, inclusiv \xeenv\u0103\u021barea automat\u0103 cuantic\u0103 (QML) \u0219i abord\u0103rile cuantice pentru ecua\u021biile cu derivate par\u021biale (PDE)."}),"\n",(0,t.jsx)(i.p,{children:"Multe dintre exemplele din acest curs sunt suficient de mici pentru a fi rezolvate de un calculator clasic. Acest lucru este inten\u021bionat. Scopul este s\u0103 \xee\u021bi oferim experien\u021b\u0103 concret\u0103 cu \xeentregul proces de utilizare a unui calculator cuantic pentru a aborda o problem\u0103 din lumea real\u0103. Unele exemple reprezint\u0103 probleme pentru care avantajul cuantic ar putea ap\u0103rea la sc\u0103ri mult mai mari. \xcen alte exemple folosim o metod\u0103 simplificat\u0103, astfel \xeenc\xe2t detaliile de implementare s\u0103 nu ascund\u0103 ideea cuantic\u0103 central\u0103."}),"\n",(0,t.jsx)(i.p,{children:"P\xe2n\u0103 la sf\xe2r\u0219itul cursului, ar trebui s\u0103 ai o imagine de ansamblu asupra principalelor aplica\u021bii cuantice \u0219i o intui\u021bie despre motivul pentru care calculatoarele cuantice ar putea fi utile \xeen anumite domenii. Vei \xeent\xe2lni tehnici comune pentru reprezentarea problemelor pe calculatoare cuantice, vei afla cum lucreaz\u0103 \xeempreun\u0103 metodele cuantice \u0219i cele clasice \u0219i vei \xeencepe s\u0103 recuno\u0219ti ce instrumente \u0219i compromisuri conteaz\u0103 pentru diferite tipuri de probleme."}),"\n",(0,t.jsx)(i.p,{children:"\xcen aceast\u0103 prim\u0103 lec\u021bie vom parcurge c\xe2teva concepte \u0219i termeni fundamentali care te ajut\u0103 s\u0103 \xeen\u021belegi la nivel \xeenalt aplica\u021biile calculului cuantic \u0219i \xee\u021bi vom oferi o imagine de ansamblu asupra principalelor domenii de aplicare pe care comunitatea \u0219tiin\u021bific\u0103 le urm\u0103re\u0219te activ."}),"\n",(0,t.jsx)(i.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Pentru ce ar putea fi utile calculatoarele cuantice"}),"\n",(0,t.jsx)(i.p,{children:"Calculatoarele cuantice sunt adesea prezentate ca rivale ale calculatoarelor clasice, dar un mod mai potrivit de a le privi este ca resurse specializate \xeen cadrul unor fluxuri de lucru clasice mai ample. \xcentrebarea important\u0103 este, a\u0219adar, care p\u0103r\u021bi ale unui calcul sunt deosebit de potrivite pentru hardware-ul cuantic. R\u0103spunsul cel mai intuitiv vine din problemele care sunt deja cuantice, cum ar fi comportamentul moleculelor, al materialelor \u0219i al c\xe2mpurilor cuantice. Un procesor cuantic poate reprezenta \u0219i manipula direct st\u0103rile cuantice, \xeen timp ce resursele necesare pentru o descriere clasic\u0103 general\u0103 cresc exponen\u021bial cu dimensiunea sistemului."}),"\n",(0,t.jsx)(i.p,{children:"Cazul este mai subtil pentru problemele cu intr\u0103ri \u0219i ie\u0219iri clasice, dar exist\u0103 totu\u0219i motive \xeentemeiate s\u0103 le explor\u0103m. Problemele de optimizare sunt larg r\u0103sp\xe2ndite \u0219i importante din punct de vedere economic, a\u0219a c\u0103 chiar \u0219i o \xeembun\u0103t\u0103\u021bire modest\u0103 a calit\u0103\u021bii solu\u021biei sau a timpului de execu\u021bie ar putea fi valoroas\u0103. Algoritmii cuantici ar putea oferi \u0219i noi moduri de a explora spa\u021bii complicate de solu\u021bii sau de a exploata structura unor clase particulare de probleme. \xcenv\u0103\u021barea automat\u0103 cuantic\u0103 are o motiva\u021bie teoretic\u0103 solid\u0103 pentru anumite probleme cu intr\u0103ri clasice, inclusiv clasificarea structurat\u0103 \u0219i procesarea seturilor de date masive. Totu\u0219i, r\u0103m\xe2ne o \xeentrebare deschis\u0103 dac\u0103 aceste rezultate se pot traduce \xeentr-un avantaj practic pe date clasice din lumea real\u0103. Ecua\u021biile cu derivate par\u021biale descriu multe sisteme importante din \u0219tiin\u021b\u0103, inginerie \u0219i finan\u021be, iar algoritmii cuantici ar putea \xeembun\u0103t\u0103\u021bi scalarea anumitor simul\u0103ri de dimensiune \xeenalt\u0103 \u0219i a unor probleme mari de algebr\u0103 liniar\u0103."}),"\n",(0,t.jsx)(i.p,{children:"\xcen toate aceste trei domenii, totu\u0219i, costul preg\u0103tirii intr\u0103rilor clasice, al rul\u0103rii calculului cuantic \u0219i al extragerii unui r\u0103spuns clasic util poate dep\u0103\u0219i beneficiul pasului cuantic. Vom \u021bine cont de aceste provoc\u0103ri practice pe m\u0103sur\u0103 ce explor\u0103m modul \xeen care metodele cuantice sunt aplicate \xeen fiecare domeniu."}),"\n",(0,t.jsx)(i.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utilitate \u0219i avantaj cuantic pe termen scurt"}),"\n",(0,t.jsx)(i.p,{children:"Acest curs nu este \xeen mod special despre avantajul cuantic, dar o discu\u021bie despre avantajul cuantic este inevitabil\u0103. Motiva\u021bia fundamental\u0103 din spatele aplica\u021biilor cuantice este de a folosi resursele cuantice pentru a extinde ceea ce pot face singure calculatoarele clasice: s\u0103 produc\u0103 rezultate mai precise, s\u0103 ajung\u0103 mai repede la solu\u021bii sau s\u0103 rezolve probleme altfel inaccesibile. Urm\u0103torii termeni \xeenrudi\u021bi ne ajut\u0103 s\u0103 vorbim clar despre progresul pe care \xeel vedem:"}),"\n",(0,t.jsxs)(i.ul,{children:["\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Accelerare cuantic\u0103:"})," Pe m\u0103sur\u0103 ce dimensiunea problemei cre\u0219te, timpul necesar unei metode cuantice scaleaz\u0103 mai favorabil dec\xe2t cel al celei mai bune metode clasice relevante pentru aceea\u0219i sarcin\u0103."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Avantaj cuantic:"})," Un calcul asistat cuantic dep\u0103\u0219e\u0219te cele mai bune abord\u0103ri clasice relevante pe o sarcin\u0103 bine definit\u0103 \u0219i cu o metric\u0103 semnificativ\u0103. Mai degrab\u0103 dec\xe2t un reper unic \u0219i permanent, avantajul cuantic este o frontier\u0103 \xeen evolu\u021bie, care se deplaseaz\u0103 pe m\u0103sur\u0103 ce se \xeembun\u0103t\u0103\u021besc at\xe2t metodele cuantice, c\xe2t \u0219i cele clasice."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Utilitate cuantic\u0103:"})," Un calcul cuantic contribuie la un rezultat \u0219tiin\u021bific sau tehnic util. Opereaz\u0103 la o scar\u0103, o ad\xe2ncime \u0219i o acurate\u021be care dep\u0103\u0219esc simularea clasic\u0103 practic\u0103 prin for\u021b\u0103 brut\u0103, f\u0103r\u0103 a dep\u0103\u0219i neap\u0103rat cea mai bun\u0103 metod\u0103 clasic\u0103."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Algoritm pe termen scurt:"})," Un algoritm conceput pentru procesoarele cuantice actuale, care folose\u0219te ad\xe2ncimi limitate ale circuitelor \u0219i se bazeaz\u0103 adesea pe postprocesare clasic\u0103 \u0219i pe atenuarea erorilor, nu pe corec\u021bia complet\u0103 a erorilor cuantice."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Calcul cuantic tolerant la erori:"})," \xcen viitor, calculul cuantic va folosi corec\u021bia erorilor cuantice pentru a proteja qubi\u021bii logici pe tot parcursul unui calcul. C\xe2nd ratele erorilor fizice sunt sub pragul de toleran\u021b\u0103 la erori, resursele suplimentare de corec\u021bie a erorilor pot suprima erorile logice p\xe2n\u0103 la nivelul de care au nevoie calculele lungi \u0219i fiabile. Toleran\u021ba la erori face posibili algoritmi mult mai ad\xe2nci, inclusiv implement\u0103ri la scar\u0103 larg\u0103 ale algoritmului lui Shor."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Toleran\u021b\u0103 timpurie la erori:"})," Toleran\u021ba la erori \xeenseamn\u0103 c\u0103 erorile sunt suprimate, nu eliminate complet. \xcen sistemele timpurii tolerante la erori, erorile logice reziduale trebuie \xeenc\u0103 luate \xeen calcul, iar ad\xe2ncimea circuitelor fiabile r\u0103m\xe2ne limitat\u0103."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"Algoritm euristic:"})," O metod\u0103 conceput\u0103 pentru a g\u0103si \xeen practic\u0103 o solu\u021bie bun\u0103, f\u0103r\u0103 a garanta r\u0103spunsul optim sau un anumit timp de execu\u021bie."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(i.h2,{id:"a-brief-foundation-in-complexity-theory",children:"O scurt\u0103 introducere \xeen teoria complexit\u0103\u021bii"}),"\n",(0,t.jsx)(i.p,{children:"\xcen unele domenii de aplicare avem un motiv teoretic puternic s\u0103 ne a\u0219tept\u0103m ca un calculator cuantic s\u0103 aib\u0103 un avantaj. Pentru a \xeen\u021belege de unde vine aceast\u0103 \xeencredere, avem nevoie de pu\u021bin vocabular din teoria complexit\u0103\u021bii."}),"\n",(0,t.jsx)(i.p,{children:"Teoria complexit\u0103\u021bii studiaz\u0103 cum cresc resursele necesare pentru rezolvarea unei probleme pe m\u0103sur\u0103 ce problema devine mai mare. Ne ofer\u0103 o hart\u0103 util\u0103 a locurilor \xeen care o accelerare cuantic\u0103 ar putea fi posibil\u0103. C\xe2\u021biva termeni sunt deosebit de importan\u021bi pentru acest curs:"}),"\n",(0,t.jsxs)(i.ul,{children:["\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"P:"})," Probleme pe care un calculator clasic le poate rezolva eficient, adic\u0103 resursele necesare cresc polinomial cu dimensiunea problemei."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"NP:"})," Probleme pentru care po\u021bi verifica eficient o solu\u021bie propus\u0103, chiar dac\u0103 g\u0103sirea acelei solu\u021bii poate fi foarte dificil\u0103."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"NP-hard:"})," Probleme care sunt cel pu\u021bin la fel de grele ca orice problem\u0103 din NP. O problem\u0103 NP-hard nu apar\u021bine neap\u0103rat clasei NP. Multe probleme de optimizare sunt NP-hard."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"NP-complete:"})," Probleme care sunt at\xe2t NP-hard, c\xe2t \u0219i \xeen NP. Acestea sunt cele mai grele probleme de decizie din NP."]}),"\n"]}),"\n",(0,t.jsxs)(i.li,{children:["\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.strong,{children:"BQP:"})," Probleme pe care un calculator cuantic le poate rezolva eficient cu o probabilitate m\u0103rginit\u0103 de eroare."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(i.p,{children:"Unele rela\u021bii dintre aceste categorii sunt cunoscute. P este con\u021binut\u0103 at\xe2t \xeen NP, c\xe2t \u0219i \xeen BQP, deoarece o problem\u0103 care poate fi rezolvat\u0103 eficient pe un calculator clasic poate fi verificat\u0103 clasic \u0219i rezolvat\u0103 pe un calculator cuantic. Alte rela\u021bii r\u0103m\xe2n deschise. Nu \u0219tim dac\u0103 P este egal\u0103 cu NP sau dac\u0103 NP este con\u021binut\u0103 \xeen BQP. Totu\u0219i, cercet\u0103torii cred \xeen general c\u0103 P este mai mic\u0103 dec\xe2t at\xe2t NP, c\xe2t \u0219i BQP \u0219i c\u0103 \u201ecalculatoarele cuantice nu pot rezolva eficient orice problem\u0103 NP-complet\u0103\u201d. Pe scurt, un calculator cuantic nu este o cutie magic\u0103 care rezolv\u0103 instantaneu orice problem\u0103 grea."}),"\n",(0,t.jsx)(i.p,{children:"Cele mai solide argumente bazate pe complexitate \xeen favoarea calculului cuantic se aplic\u0103 unor tipuri particulare de probleme. Algoritmul lui Shor scaleaz\u0103 dramatic mai bine dec\xe2t cei mai buni algoritmi clasici cunoscu\u021bi pentru factorizare \u0219i logaritmi discre\u021bi, de\u0219i nu s-a demonstrat c\u0103 factorizarea se afl\u0103 \xeen afara clasei P. Simularea cuantic\u0103 general\u0103 are, de asemenea, o fundamentare teoretic\u0103 solid\u0103. Unele probleme de simulare cuantic\u0103 sunt BQP-complete, ceea ce \xeenseamn\u0103 c\u0103 rezolvarea lor clasic\u0103 eficient\u0103 ar echivala cu simularea eficient\u0103 a oric\u0103rui calcul cuantic. O asemenea simulare clasic\u0103 eficient\u0103 este foarte improbabil\u0103, motiv pentru care simularea hamiltonian\u0103 cuantic\u0103 este considerat\u0103 un domeniu de aplicare at\xe2t de promi\u021b\u0103tor."}),"\n",(0,t.jsx)(i.p,{children:"Unele PDE de dimensiune \xeenalt\u0103 pot fi reduse la probleme de sisteme liniare BQP-complete, ceea ce ne d\u0103 un motiv puternic s\u0103 ne a\u0219tept\u0103m la o accelerare cuantic\u0103 atunci c\xe2nd intr\u0103rile \u0219i ie\u0219irile pot fi gestionate eficient. QML are exemple similare: unele sarcini care implic\u0103 date cuantice sunt BQP-complete, iar unele modele cuantice pot genera e\u0219antioane greu de reprodus clasic."}),"\n",(0,t.jsx)(i.p,{children:"Cazul este mai pu\u021bin direct pentru optimizare. Nu ne a\u0219tept\u0103m ca calculatoarele cuantice s\u0103 rezolve eficient probleme NP-hard arbitrare, dar ele ar putea totu\u0219i ajuta la probleme structurate, la instan\u021be particulare sau la pa\u0219i specifici dintr-un flux de lucru de optimizare. Algoritmul lui Grover, de exemplu, ofer\u0103 o accelerare p\u0103tratic\u0103 pentru c\u0103utarea nestructurat\u0103. Aceasta este o \xeembun\u0103t\u0103\u021bire semnificativ\u0103, chiar dac\u0103 r\u0103d\u0103cina p\u0103trat\u0103 a unui spa\u021biu de c\u0103utare astronomic de mare poate r\u0103m\xe2ne astronomic\u0103."}),"\n",(0,t.jsx)(i.h2,{id:"from-complexity-theory-to-practical-evidence",children:"De la teoria complexit\u0103\u021bii la dovezi practice"}),"\n",(0,t.jsx)(i.p,{children:"Teoria complexit\u0103\u021bii ne poate spune unde ar putea fi posibil\u0103 o accelerare cuantic\u0103, dar de obicei nu ne poate spune cum se comport\u0103 o metod\u0103 pe o problem\u0103 anume sau pe un anumit calculator cuantic. Multe dintre metodele folosite pe hardware-ul actual sunt euristice. Ele sunt concepute pentru a g\u0103si r\u0103spunsuri bune \xeen practic\u0103, dar nu garanteaz\u0103 cel mai bun r\u0103spuns posibil sau un anumit timp de execu\u021bie."}),"\n",(0,t.jsx)(i.p,{children:"Euristicile nu sunt specifice calculului cuantic, iar faptul c\u0103 o metod\u0103 este numit\u0103 euristic\u0103 nu \xeenseamn\u0103 c\u0103 este nefiabil\u0103 sau ne\u0219tiin\u021bific\u0103. Optimizarea clasic\u0103, \xeenv\u0103\u021barea automat\u0103 \u0219i chimia computa\u021bional\u0103 se bazeaz\u0103 intens pe euristici atunci c\xe2nd o solu\u021bie exact\u0103 ar fi prea costisitoare. O euristic\u0103 cuantic\u0103 ar putea oferi un mod nou de a explora un spa\u021biu de solu\u021bii, de a preg\u0103ti st\u0103ri utile sau de a identifica candida\u021bi promi\u021b\u0103tori. Dac\u0103 func\u021bioneaz\u0103 bine este o \xeentrebare empiric\u0103: trebuie s\u0103 o rul\u0103m \u0219i s\u0103 m\u0103sur\u0103m rezultatul."}),"\n",(0,t.jsx)(i.p,{children:"Deoarece euristicile nu vin cu garan\u021bii de performan\u021b\u0103, le evalu\u0103m folosind o metric\u0103 de succes clar\u0103, valori de referin\u021b\u0103 clasice solide \u0219i teste pe diferite dimensiuni ale problemei. Acest lucru ne ajut\u0103 s\u0103 vedem unde func\u021bioneaz\u0103 bine o metod\u0103 \u0219i cum se schimb\u0103 performan\u021ba ei pe m\u0103sur\u0103 ce problema cre\u0219te."}),"\n",(0,t.jsx)(i.h2,{id:"application-areas-and-course-case-studies",children:"Domenii de aplicare \u0219i studii de caz ale cursului"}),"\n",(0,t.jsx)(i.p,{children:"Organiz\u0103m cursul \xeen jurul a patru domenii largi de aplicare. Ele nu acoper\u0103 toate utiliz\u0103rile posibile ale unui calculator cuantic, dar ne ofer\u0103 un mod util de a compara unde se afl\u0103 cele mai solide argumente \u0219i unde sunt \xeentreb\u0103rile deschise."}),"\n",(0,t.jsx)(i.h3,{id:"hamiltonian-simulation",children:"Simulare hamiltonian\u0103"}),"\n",(0,t.jsx)(i.p,{children:"Simularea hamiltonian\u0103 include estimarea energiilor, studiul propriet\u0103\u021bilor chimice \u0219i ale materialelor \u0219i modelarea modului \xeen care sistemele cuantice se schimb\u0103 \xeen timp. Se extinde \xeen chimie, \u0219tiin\u021ba materialelor, fizica materiei condensate \u0219i fizica energiilor \xeenalte \u0219i nuclear\u0103. Studiile noastre de caz examineaz\u0103 un model puternic corelat fier-sulf folosind diagonalizarea cuantic\u0103 bazat\u0103 pe e\u0219antioane \u0219i simuleaz\u0103 dinamica hadronilor folosind o reprezentare pe re\u021bea care \u021bine cont de simetrii. Acestea sunt dou\u0103 exemple dintr-un domeniu mult mai larg, care include \u0219i mecanisme de reac\u021bie, materiale magnetice \u0219i alte dinamici ale sistemelor cu multe corpuri."}),"\n",(0,t.jsx)(i.h3,{id:"optimization",children:"Optimizare"}),"\n",(0,t.jsx)(i.p,{children:"Optimizarea apare peste tot, de la finan\u021be \u0219i logistic\u0103 p\xe2n\u0103 la planificare \u0219i sisteme energetice. Este \u0219i un domeniu \xeen care avantajul este greu de stabilit, deoarece rezolvitorii clasici sunt extrem de capabili, iar transpunerile cuantice pot ad\u0103uga o suprasarcin\u0103 costisitoare. Studiul nostru de caz folose\u0219te selec\u021bia de portofoliu pentru a explora cum este reprezentat\u0103, rulat\u0103 \u0219i evaluat\u0103 comparativ o problem\u0103 de optimizare, f\u0103r\u0103 a presupune c\u0103 un calculator cuantic g\u0103se\u0219te automat optimul exact."}),"\n",(0,t.jsx)(i.h3,{id:"quantum-machine-learning",children:"\xcenv\u0103\u021bare automat\u0103 cuantic\u0103"}),"\n",(0,t.jsx)(i.p,{children:"\xcenv\u0103\u021barea automat\u0103 cuantic\u0103 se \xeentreab\u0103 dac\u0103 circuitele cuantice sau datele cuantice pot \xeembun\u0103t\u0103\u021bi o sarcin\u0103 de \xeenv\u0103\u021bare. \xcentreb\u0103rile importante includ codificarea datelor, costul antren\u0103rii, generalizarea \u0219i compararea cu modele clasice puternice."}),"\n",(0,t.jsx)(i.h3,{id:"partial-differential-equations",children:"Ecua\u021bii cu derivate par\u021biale"}),"\n",(0,t.jsx)(i.p,{children:"Ecua\u021biile cu derivate par\u021biale descriu sisteme precum fluidele, c\u0103ldura \u0219i undele. Algoritmii cuantici ar putea accelera p\u0103r\u021bi din unele fluxuri de lucru PDE, dar preg\u0103tirea datelor \u0219i extragerea unui r\u0103spuns clasic util pot fi costuri majore. Studiul de caz specific este \xeenc\u0103 \xeen curs de dezvoltare."}),"\n",(0,t.jsx)(i.p,{children:"\xcen lec\u021biile urm\u0103toare vom pune acelea\u0219i \xeentreb\u0103ri de baz\u0103 \xeen fiecare domeniu: care este problema, de ce ar putea ajuta calculul cuantic, care sunt limit\u0103rile \u0219i ce arat\u0103 de fapt dovezile? Vom \xeencepe cu simularea hamiltonian\u0103, unde problema \xeen sine este cuantic\u0103."}),"\n",(0,t.jsx)(i.h2,{id:"conclusion",children:"Concluzie"}),"\n",(0,t.jsx)(i.p,{children:"Am parcurs mult teren, dar ideea principal\u0103 este simpl\u0103: calculatoarele cuantice sunt instrumente specializate, iar valoarea lor depinde de folosirea metodei cuantice potrivite pentru problema potrivit\u0103 sau pentru o parte dintr-o problem\u0103 mai mare. Simularea hamiltonian\u0103 are cea mai clar\u0103 fundamentare teoretic\u0103, optimizarea dispune de un set matur de metode euristice \u0219i valori de referin\u021b\u0103, iar QML \u0219i PDE ofer\u0103 direc\u021bii promi\u021b\u0103toare care \xeenc\u0103 se dezvolt\u0103."}),"\n",(0,t.jsx)(i.p,{children:"\xcen lec\u021biile urm\u0103toare vom trece de la aceast\u0103 privire de ansamblu la exemple practice. Pentru fiecare aplica\u021bie vom \xeentreba ce problem\u0103 \xeencerc\u0103m s\u0103 rezolv\u0103m, ce rol are calculatorul cuantic, cum este interpretat rezultatul \u0219i ce putem \xeenv\u0103\u021ba din el. Scopul este s\u0103 \xee\u021bi construie\u0219ti intui\u021bia despre unde ar putea ajuta calculul cuantic \u0219i ce trebuie f\u0103cut pentru a transforma o idee promi\u021b\u0103toare \xeentr-un calcul real."}),"\n"]})}function p(e={}){const{wrapper:i}={...(0,c.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(s,{...e})}):s(e)}},28453(e,i,a){a.d(i,{R:()=>n,x:()=>l});var r=a(96540);const t={},c=r.createContext(t);function n(e){const i=r.useContext(c);return r.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:n(e.components),r.createElement(c.Provider,{value:i},e.children)}}}]);